        if (-not (Test-Path -LiteralPath $outputPath)) {
            throw "SuperCollider reported success but did not create $outputPath."
        }
    }
}
finally {
    Remove-Item Env:EEG_HARMONICS_TEST -ErrorAction SilentlyContinue
