param(
    [string]$SclangPath = "",
    [string]$OutputDirectory = ""
)

$ErrorActionPreference = "Stop"
$projectRoot = Split-Path -Parent $PSScriptRoot
if ([string]::IsNullOrWhiteSpace($OutputDirectory)) {
    $OutputDirectory = Join-Path $projectRoot "recordings\eeg_organism_v2_voicing"
}
if ([string]::IsNullOrWhiteSpace($SclangPath)) {
    $SclangPath = @(
        "D:\OpenBCI\supercollider\sclang.exe",
        "C:\Program Files\SuperCollider-3.14.1\sclang.exe",
        "C:\Program Files\SuperCollider\sclang.exe"
    ) | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
}
if ([string]::IsNullOrWhiteSpace($SclangPath) -or
    -not (Test-Path -LiteralPath $SclangPath)) {
    throw "sclang was not found. Pass -SclangPath with the full path."
}

New-Item -ItemType Directory -Path $OutputDirectory -Force | Out-Null
$renderScript = Join-Path $projectRoot "sound\render_eeg_organism_v2_voicing_transition.scd"
$outputPath = Join-Path $OutputDirectory "g_lydian_transition.wav"
$archivePath = Join-Path $OutputDirectory "archive.sctxar"
if (Test-Path -LiteralPath $archivePath) {
    throw "Refusing to overwrite pre-existing temporary archive $archivePath."
}
try {
    $env:EEG_ORGANISM_V2_OUTPUT = $outputPath
    $env:EEG_ORGANISM_V2_ARCHIVE_DIR = $OutputDirectory
    $renderLog = & $SclangPath -D $renderScript 2>&1
    $renderLog | ForEach-Object { Write-Host $_ }
    if ($LASTEXITCODE -ne 0) {
        throw "SuperCollider render failed with exit code $LASTEXITCODE."
    }
    $renderText = $renderLog -join [Environment]::NewLine
    if ($renderText -match "ERROR:|FAILURE IN SERVER|exception in GraphDef_Recv") {
        throw "SuperCollider reported a synthesis/render error."
    }
    if (-not (Test-Path -LiteralPath $outputPath)) {
        throw "SuperCollider did not create $outputPath."
    }
}
finally {
    Remove-Item Env:EEG_ORGANISM_V2_OUTPUT -ErrorAction SilentlyContinue
    Remove-Item Env:EEG_ORGANISM_V2_ARCHIVE_DIR -ErrorAction SilentlyContinue
    if (Test-Path -LiteralPath $archivePath) {
        Remove-Item -LiteralPath $archivePath -Force
    }
}
Write-Host "Rendered persistent voice-bank transition -> $outputPath"

param(
    [ValidateSet("synthetic-supercollider", "isolated-supercollider", "family-supercollider", "supercollider-live")]
    [string]$Mode = "synthetic-supercollider",

    [ValidateSet("energy", "centroid", "mobility", "all")]
    [string]$Descriptor = "all",

    [ValidateSet("F3", "F4", "C3", "C4", "P3", "P4", "all")]
    [string]$Channel = "all",

    [double]$ControlHz = 0,
    [string]$Config = ""
)

$ErrorActionPreference = "Stop"
$projectRoot = Split-Path -Parent $PSScriptRoot
if ([string]::IsNullOrWhiteSpace($Config)) {
    $Config = Join-Path $projectRoot "config\sonification.toml"
}

$venvPython = Join-Path $projectRoot ".venv\Scripts\python.exe"
$pythonCommand = if (Test-Path -LiteralPath $venvPython) { $venvPython } else { "python" }
$arguments = @(
    "-m", "src.eeg_control_demo",
    "--mode", $Mode,
    "--config", $Config,
    "--sweep-descriptor", $Descriptor,
    "--sweep-channel", $Channel
)
if ($ControlHz -gt 0) {
    $arguments += @("--control-hz", $ControlHz.ToString([Globalization.CultureInfo]::InvariantCulture))
}

Write-Host "SuperCollider must already show 'EEG ORGANISM PHASE 1B READY on UDP 57120'."
if ($Mode -eq "isolated-supercollider" -and ($Descriptor -eq "all" -or $Channel -eq "all")) {
    throw "isolated-supercollider requires -Descriptor energy|centroid|mobility and -Channel F3|F4|C3|C4|P3|P4"
}
Write-Host "Starting $Mode; press Ctrl+C to stop Python. The SC watchdog will then fade output."
Push-Location $projectRoot
try {
    & $pythonCommand @arguments
}
finally {
    Pop-Location
}

param(
    [string]$Config = ""
)

$ErrorActionPreference = "Stop"
$projectRoot = Split-Path -Parent $PSScriptRoot
if ([string]::IsNullOrWhiteSpace($Config)) {
    $Config = Join-Path $projectRoot "config\sonification.toml"
}

$venvPython = Join-Path $projectRoot ".venv\Scripts\python.exe"
$pythonCommand = if (Test-Path -LiteralPath $venvPython) { $venvPython } else { "python" }

Push-Location $projectRoot
try {
    & $pythonCommand -m src.eeg_control_demo --mode stop-supercollider --config $Config
}
finally {
    Pop-Location
}

(
// Python sends OSC here.
thisProcess.openUDPPort(9000);

s.boot;

s.waitForBoot({
    SynthDef(\biosignalInstrument, {
        |eegLow = 0.2,
        eegMid = 0.3,
        eegHigh = 0.5,
        eog = 0.0,
        emg = 0.0|

        var low;
        var mid;
        var high;
        var eye;
        var muscle;
        var baseFrequency;
        var pitchMovement;
        var tonalLayer;
        var muscleLayer;
        var output;

        // Smooth control changes and prevent clicks.
        low = Lag.kr(eegLow.clip(0, 1), 1.5);
        mid = Lag.kr(eegMid.clip(0, 1), 1.5);
        high = Lag.kr(eegHigh.clip(0, 1), 1.5);
        eye = Lag.kr(eog.clip(0, 1), 0.5);
        muscle = Lag.kr(emg.clip(0, 1), 0.15);

        // EEG proportions define the continuous tonal layer.
        baseFrequency = mid.linexp(0, 1, 110, 260);

        pitchMovement = SinOsc.kr(
            low.linlin(0, 1, 0.05, 0.5)
        ).range(
            1 - (eye * 0.04),
            1 + (eye * 0.04)
        );

        tonalLayer = SinOsc.ar(
            [
                baseFrequency * pitchMovement,
                baseFrequency * 1.005 * pitchMovement
            ],
            0,
            0.025
        );

        tonalLayer = tonalLayer + SinOsc.ar(
            [
                baseFrequency * 2,
                baseFrequency * 2.01
            ],
            0,
            high * 0.008
        );

        // EMG adds continuous texture, not an event sound.
        muscleLayer = BPF.ar(
            WhiteNoise.ar(0.025 ! 2),
            muscle.linexp(0, 1, 500, 4000),
            0.25
        ) * muscle;

        output = tonalLayer + muscleLayer;

        // Protect against clipped controls and excessive output.
        output = LeakDC.ar(output);
        output = Limiter.ar(output, 0.08);

        Out.ar(0, output);
    }).add;

    s.sync;

    ~biosignalInstrument = Synth(\biosignalInstrument);

    OSCdef(
        \eegLowInput,
        { |message|
            ~biosignalInstrument.set(
                \eegLow,
                message[1].asFloat.clip(0, 1)
            );
        },
        "/eeg/4_8",
        recvPort: 9000
    );

    OSCdef(
        \eegMidInput,
        { |message|
            ~biosignalInstrument.set(
                \eegMid,
                message[1].asFloat.clip(0, 1)
            );
        },
        "/eeg/8_13",
        recvPort: 9000
    );

    OSCdef(
        \eegHighInput,
        { |message|
            ~biosignalInstrument.set(
                \eegHigh,
                message[1].asFloat.clip(0, 1)
            );
        },
        "/eeg/13_30",
        recvPort: 9000
    );

    OSCdef(
        \eogInput,
        { |message|
            ~biosignalInstrument.set(
                \eog,
                message[1].asFloat.clip(0, 1)
            );
        },
        "/body/eog",
        recvPort: 9000
    );

    OSCdef(
        \emgInput,
        { |message|
            ~biosignalInstrument.set(
                \emg,
                message[1].asFloat.clip(0, 1)
            );
        },
        "/body/emg",
        recvPort: 9000
    );

    "BIOSIGNAL INSTRUMENT READY".postln;
});
)

(
// Known failure case: another receiver is using port 9000.
if(thisProcess.openUDPPort(9000).not) {
    Error(
        "UDP port 9000 is unavailable. Stop osc_receiver.py first."
    ).throw;
};

s.options.numOutputBusChannels = 2;
s.boot;

s.waitForBoot({
    SynthDef(\agoraDuet, {
        |out = 0,
        eegLow = 0.2,
        eegMid = 0.3,
        eegHigh = 0.5,
        eog = 0.0,
        emg = 0.0,
        master = 0.6|

        var low;
        var mid;
        var high;
        var eye;
        var muscle;

        var phraseRate;
        var melodyTrigger;
        var degree;
        var baseMidi;
        var melodyFrequency;
        var melodyEnvelope;
        var melody;

        var droneFrequencies;
        var droneAmplitudes;
        var drone;
        var tonalLayer;

        var bodyRate;
        var bodyTrigger;
        var bodyEnvelope;
        var bodyCentre;
        var bodyTexture;

        var spatialTone;
        var output;

        // Smooth data changes so OSC updates do not click.
        low = Lag.kr(eegLow.clip(0, 1), 2.0);
        mid = Lag.kr(eegMid.clip(0, 1), 2.0);
        high = Lag.kr(eegHigh.clip(0, 1), 2.0);
        eye = Lag.kr(eog.clip(0, 1), 0.6);
        muscle = Lag.kr(emg.clip(0, 1), 0.18);

        // Autonomous melodic phrase.
        // EEG shapes its pace and register, not its semantic meaning.
        phraseRate = low.linexp(0, 1, 0.12, 0.70);
        melodyTrigger = Impulse.kr(phraseRate);

        degree = Demand.kr(
            melodyTrigger,
            0,
            Dseq(
                [0, 7, 2, 9, 5, 4, 11, 7],
                inf
            )
        );

        baseMidi = 43 + degree + (mid * 7);

        // EOG activity changes glide continuously.
        melodyFrequency = Lag.kr(
            baseMidi.midicps,
            eye.linlin(0, 1, 0.15, 2.0)
        );

        melodyEnvelope = Decay2.kr(
            melodyTrigger,
            0.25,
            3.5
        );

        melody = SinOsc.ar(
            [
                melodyFrequency,
                melodyFrequency * 1.004
            ],
            0,
            melodyEnvelope * 0.018
        );

        // Slowly moving harmonic field.
        droneFrequencies = (
            [55, 82.5, 110, 165]
            * (
                1
                + LFNoise2.kr(
                    [0.031, 0.043, 0.057, 0.071]
                ).range(-0.003, 0.003)
            )
        );

        droneAmplitudes = (
            [
                low,
                mid,
                high,
                (mid + high) * 0.5
            ]
            * [0.018, 0.015, 0.010, 0.007]
        );

        drone = Splay.ar(
            SinOsc.ar(
                droneFrequencies,
                0,
                droneAmplitudes
            ),
            spread: 0.8,
            level: 1.0
        );

        // High-band proportion changes spectral brightness.
        tonalLayer = LPF.ar(
            drone + melody,
            high.linexp(0, 1, 900, 6500)
        );

        // EMG controls the density and brightness of a
        // continuous stochastic texture.
        bodyRate = muscle.linexp(0, 1, 0.4, 14);
        bodyTrigger = Dust.kr(bodyRate);

        bodyEnvelope = Decay2.kr(
            bodyTrigger,
            0.01,
            muscle.linlin(0, 1, 0.08, 0.35)
        );

        bodyCentre = LFNoise2.kr(
            bodyRate.linlin(0.4, 14, 0.2, 3)
        ).exprange(350, 4800);

        bodyTexture = BPF.ar(
            PinkNoise.ar(0.04 ! 2),
            bodyCentre,
            0.22
        ) * bodyEnvelope * muscle;

        // EOG controls depth/space rather than left/right eye position.
        spatialTone = FreeVerb2.ar(
            tonalLayer[0],
            tonalLayer[1],
            mix: eye.linlin(0, 1, 0.12, 0.55),
            room: 0.82,
            damp: 0.55
        );

        output = spatialTone + bodyTexture;
        output = LeakDC.ar(output);
        output = Limiter.ar(output, 0.08);
        output = output * master;

        Out.ar(out, output);
    }).add;

    s.sync;

    ~agoraDuet = Synth(\agoraDuet);

    OSCdef(
        \eegLowInput,
        { |message|
            ~agoraDuet.set(
                \eegLow,
                message[1].asFloat.clip(0, 1)
            );
        },
        '/eeg/4_8',
        recvPort: 9000
    );

    OSCdef(
        \eegMidInput,
        { |message|
            ~agoraDuet.set(
                \eegMid,
                message[1].asFloat.clip(0, 1)
            );
        },
        '/eeg/8_13',
        recvPort: 9000
    );

    OSCdef(
        \eegHighInput,
        { |message|
            ~agoraDuet.set(
                \eegHigh,
                message[1].asFloat.clip(0, 1)
            );
        },
        '/eeg/13_30',
        recvPort: 9000
    );

    OSCdef(
        \eogInput,
        { |message|
            ~agoraDuet.set(
                \eog,
                message[1].asFloat.clip(0, 1)
            );
        },
        '/body/eog',
        recvPort: 9000
    );

    OSCdef(
        \emgInput,
        { |message|
            ~agoraDuet.set(
                \emg,
                message[1].asFloat.clip(0, 1)
            );
        },
        '/body/emg',
        recvPort: 9000
    );

    "AGORA DUET READY — listening on UDP 9000".postln;
});
)

(
OSCdef(\eegLowInput).free;
OSCdef(\eegMidInput).free;
OSCdef(\eegHighInput).free;
OSCdef(\eogInput).free;
OSCdef(\emgInput).free;

~agoraDuet.free;

"AGORA DUET STOPPED".postln;
)

// Shared synthesis definition for the disconnected Harmonics instrument.
//
// The musical mapping principle is adapted from Stephen Whitmarsh / EEGsynth.
// This is an original SuperCollider implementation; it does not load EEGsynth,
// FieldTrip, or Redis and does not claim to reproduce Verbos hardware timbre.
// Evaluating this file only defines a factory function.

~makeEegHarmonicFieldSynthDef = { |defName = \eegManualHarmonicField, preset|
    if(preset.isNil) { Error("A centralized harmonic preset is required.").throw };

    SynthDef(defName, {
        |out = 0, gate = 1|
        var harmonicNumbers, fundamental, harmonicCount, harmonicRollOff;
        var groupControls, groupTrims, groupLoudnessComp, panPositions;
        var groupLevels, partialLoudnessComp;
        var spectralShapes, perceptualWeights, perceptualNorm, partials;
        var controlLag, energyLag, width, source, delayed, delayMix;
        var energy, energyAmp, saturated, wet, signal, life;
        var saturationDrive, limiterDb;

        harmonicNumbers = (1..12);
        controlLag = NamedControl.kr(\controlLag, preset[\controlLag]).clip(0.02, 8);
        energyLag = NamedControl.kr(\energyLag, preset[\energyLag]).clip(0.02, 8);
        fundamental = VarLag.kr(
            NamedControl.kr(\fundamental, preset[\fundamental]),
            controlLag, warp: -4
        );
        harmonicCount = NamedControl.kr(\harmonicCount, preset[\harmonicCount]);
        harmonicRollOff = VarLag.kr(
            NamedControl.kr(\harmonicRollOff, preset[\harmonicRollOff]),
            controlLag, warp: -4
        );
        groupControls = NamedControl.kr(\groupAmplitudes, preset[\baseGroups]);
        groupTrims = NamedControl.kr(\groupTrims, preset[\groupTrims]);
        groupLoudnessComp = NamedControl.kr(
            \groupLoudnessComp,
            preset[\groupLoudnessComp]
        );
        panPositions = NamedControl.kr(\panPositions, preset[\panPositions]);

        groupControls = groupControls.collect { |value|
            VarLag.kr(value.clip(0, 1), controlLag, warp: -4)
        };
        groupTrims = groupTrims.collect { |value|
            VarLag.kr(value.clip(0.1, 2), controlLag, warp: -4)
        };
        groupLoudnessComp = groupLoudnessComp.collect { |value|
            VarLag.kr(value.clip(0.25, 2), controlLag, warp: -4)
        };
        panPositions = panPositions.collect { |value|
            VarLag.kr(value.clip(-1, 1), controlLag, warp: -4)
        };
        width = VarLag.kr(
            NamedControl.kr(\stereoWidth, preset[\stereoWidth]).clip(0, 1),
            controlLag, warp: -4
        );

        // 12 partials: 1-3, 4-6, 7-9, 10-12. Eight partials: pairs.
        groupLevels = harmonicNumbers.collect { |harmonic|
            var groupFor12, groupFor8, trimFor12, trimFor8, useEight, active;
            groupFor12 = groupControls[((harmonic - 1) / 3).floor];
            groupFor8 = groupControls[(((harmonic - 1) / 2).floor).min(3)];
            trimFor12 = groupTrims[((harmonic - 1) / 3).floor];
            trimFor8 = groupTrims[(((harmonic - 1) / 2).floor).min(3)];
            useEight = harmonicCount <= 8;
            active = Lag.kr(harmonic <= harmonicCount, controlLag);
            Select.kr(useEight,
                [groupFor12 * trimFor12, groupFor8 * trimFor8]) * active;
        };
        partialLoudnessComp = harmonicNumbers.collect { |harmonic|
            var compFor12, compFor8, useEight;
            compFor12 = groupLoudnessComp[((harmonic - 1) / 3).floor];
            compFor8 = groupLoudnessComp[(((harmonic - 1) / 2).floor).min(3)];
            useEight = harmonicCount <= 8;
            Select.kr(useEight, [compFor12, compFor8]);
        };

        // Trim and roll-off live inside the same perceptual-energy norm.
        spectralShapes = harmonicNumbers.collect { |harmonic, index|
            groupLevels[index] * (harmonic ** harmonicRollOff.neg)
        };
        perceptualNorm = (spectralShapes.collect(_.squared).sum + 1e-9).sqrt;

        // Capped inverse A-weighting is a pragmatic approximation, not a model
        // of human hearing.
        perceptualWeights = harmonicNumbers.collect { |harmonic, index|
            var frequency, f2, numerator, denominator, aDb, compensation;
            frequency = fundamental.clip(40, 160) * harmonic;
            f2 = frequency.squared;
            numerator = 12194.squared * f2.squared;
            denominator = (f2 + 20.6.squared)
                * ((f2 + 107.7.squared) * (f2 + 737.9.squared)).sqrt
                * (f2 + 12194.squared);
            aDb = (numerator / denominator).ampdb + 2.0;
            compensation = aDb.neg.dbamp.clip(0.35, 5.0);
            spectralShapes[index] * compensation
                * partialLoudnessComp[index] / perceptualNorm;
        };

        partials = harmonicNumbers.collect { |harmonic, index|
            Pan2.ar(
                SinOsc.ar(fundamental.clip(40, 160) * harmonic, 0,
                    perceptualWeights[index]),
                panPositions[index].clip(-1, 1) * width
            )
        };
        source = LeakDC.ar(Mix(partials));

        // Fixed cross-channel delay only: no feedback and no modulation.
        delayed = [
            DelayC.ar(source[1], 0.08,
                NamedControl.kr(\delayTimeLeft, preset[\delayTimeLeft]).clip(0.001, 0.08)),
            DelayC.ar(source[0], 0.08,
                NamedControl.kr(\delayTimeRight, preset[\delayTimeRight]).clip(0.001, 0.08))
        ];
        delayMix = VarLag.kr(
            NamedControl.kr(\delayMix, preset[\delayMix]).clip(0, 0.15),
            controlLag, warp: -4
        );
        source = XFade2.ar(source, delayed, (delayMix * 2) - 1);

        // Master energy is strictly post-spectrum gain.
        energy = VarLag.kr(
            NamedControl.kr(\masterEnergy, preset[\masterEnergy]).clip(0, 1),
            energyLag, warp: -4
        );
        energyAmp = energy.linlin(
            0, 1,
            NamedControl.kr(\energyMinDb, preset[\energyMinDb]),
            NamedControl.kr(\energyMaxDb, preset[\energyMaxDb])
        ).dbamp;
        source = source * energyAmp;

        saturationDrive = VarLag.kr(
            NamedControl.kr(\saturationDrive, preset[\saturationDrive]),
            controlLag, warp: -4
        ).clip(1, 2);
        saturated = (source * saturationDrive).tanh / saturationDrive;

        wet = GVerb.ar(
            saturated.sum * 0.5,
            roomsize: NamedControl.kr(\reverbRoom, preset[\reverbRoom]).clip(8, 80),
            revtime: NamedControl.kr(\reverbTime, preset[\reverbTime]).clip(0.5, 12),
            damping: NamedControl.kr(\reverbDamping, preset[\reverbDamping]).clip(0, 1),
            inputbw: NamedControl.kr(\reverbInputBw, preset[\reverbInputBw]).clip(0.1, 1),
            spread: NamedControl.kr(\reverbSpread, preset[\reverbSpread]).clip(0, 43),
            drylevel: 0,
            earlyreflevel: NamedControl.kr(\reverbEarly, preset[\reverbEarly]).clip(0, 1),
            taillevel: NamedControl.kr(\reverbTail, preset[\reverbTail]).clip(0, 1),
            maxroomsize: 80
        );
        signal = XFade2.ar(
            saturated, wet,
            (VarLag.kr(
                NamedControl.kr(\reverbMix, preset[\reverbMix]).clip(0, 1),
                controlLag, warp: -4
            ) * 2) - 1
        );

        life = EnvGen.kr(
            Env.asr(
                NamedControl.kr(\attack, preset[\attack]).clip(0.05, 8), 1,
                NamedControl.kr(\release, preset[\release]).clip(0.1, 15),
                curve: -4
            ),
            gate,
            doneAction: 2
        );
        limiterDb = NamedControl.kr(\limiterDb, preset[\limiterDb]).clip(-12, -0.1);
        signal = Limiter.ar(
            signal * VarLag.kr(
                NamedControl.kr(\outputTrim, preset[\outputTrim]).clip(0, 1),
                controlLag, warp: -4
            ) * life,
            limiterDb.dbamp, 0.01
        );
        Out.ar(out, signal);
    });
};

// Targeted v2 variant of the tested additive harmonic field.
//
// The topology remains one continuous exact-harmonic oscillator field, fixed stereo
// placement/delay, restrained saturation, GVerb, and limiter. The v2 core has
// two internal six-slot banks so pitch material can crossfade without creating
// nodes or changing the approved timbre. Evaluating this file only defines a
// factory function.

~makeEegOrganismV2HarmonicFieldSynthDef = {
    |defName = \eegOrganismV2HarmonicField, preset|
    var harmonicGroups, harmonicNumbers, groupIndexes, betaHarmonics;
    var betaLowestHarmonic, betaHighestHarmonic;
    var voiceCapacity, defaultVoiceFrequencies, defaultVoiceWeights;
    var weightedShapes, groupWavetables, groupEnergyScales, groupPanPositions;
    var wavetableSignalSize, maximumHarmonic;
    if(preset.isNil) { Error("A centralized v2 harmonic preset is required.").throw };
    harmonicGroups = preset[\harmonicGroups];
    if(harmonicGroups.isNil or: { harmonicGroups.size != 4 }) {
        Error("The v2 preset must define exactly four harmonicGroups.").throw
    };
    harmonicNumbers = harmonicGroups.flat;
    betaHarmonics = harmonicGroups[3];
    betaLowestHarmonic = betaHarmonics.minItem;
    betaHighestHarmonic = betaHarmonics.maxItem;
    voiceCapacity = preset[\voiceCapacity] ? 6;
    if(voiceCapacity != 6) {
        Error("The organism v2 voiceCapacity must remain exactly six.").throw
    };
    defaultVoiceFrequencies = Array.fill(voiceCapacity, preset[\fundamental]);
    defaultVoiceWeights = [1.0] ++ Array.fill(voiceCapacity - 1, 0.0);
    groupIndexes = harmonicGroups.collect { |group, index|
        Array.fill(group.size, index)
    }.flat;
    wavetableSignalSize = 128;
    maximumHarmonic = harmonicNumbers.maxItem;

    // Compile the approved harmonic envelope into four small persistent local
    // wavetables. This keeps the graph narrow enough for an already-running
    // default scsynth while preserving every configured exact harmonic number.
    weightedShapes = harmonicNumbers.collect { |harmonic, index|
        var frequency, f2, numerator, denominator, aDb, compensation;
        var groupIndex, betaShape, betaPosition, ceilingRatio, betaTrim;
        groupIndex = groupIndexes[index];
        frequency = preset[\fundamental] * harmonic;
        f2 = frequency.squared;
        numerator = 12194.squared * f2.squared;
        denominator = (f2 + 20.6.squared)
            * ((f2 + 107.7.squared) * (f2 + 737.9.squared)).sqrt
            * (f2 + 12194.squared);
        aDb = (numerator / denominator).ampdb + 2.0;
        compensation = aDb.neg.dbamp.clip(0.35, 5.0);
        betaShape = if(groupIndex == 3) {
            betaPosition = (harmonic - betaLowestHarmonic)
                / (betaHighestHarmonic - betaLowestHarmonic).max(1);
            ceilingRatio = (frequency / preset[\betaCeilingHz]).max(1.0);
            (betaPosition * preset[\betaUpperPartialTiltDb]).dbamp
                * ceilingRatio.squared.reciprocal
        } {
            1.0
        };
        betaTrim = if(groupIndexes[index] == 3) { preset[\betaTrim] } { 1.0 };
        preset[\groupTrims][groupIndex]
            * preset[\groupLoudnessComp][groupIndex]
            * (harmonic ** preset[\harmonicRollOff].neg)
            * compensation
            * betaShape
            * betaTrim;
    };
    if(weightedShapes.collect(_.squared).sum <= 0) {
        Error("The organism v2 harmonic envelope must have nonzero energy.").throw
    };
    groupWavetables = harmonicGroups.collect { |group|
        var amplitudes, signal;
        amplitudes = Array.fill(maximumHarmonic, 0.0);
        group.do { |harmonic|
            amplitudes[harmonic - 1] = weightedShapes[harmonicNumbers.indexOf(harmonic)]
        };
        // Instance sineFill deliberately avoids class-side peak normalization;
        // groupEnergyScales below is therefore the single level normalizer.
        signal = Signal.newClear(wavetableSignalSize);
        signal.sineFill(amplitudes);
        signal.asWavetable;
    };
    groupEnergyScales = harmonicGroups.collect { |group|
        (group.collect { |harmonic|
            weightedShapes[harmonicNumbers.indexOf(harmonic)].squared
        }.sum + 1e-9).sqrt
    };
    groupPanPositions = harmonicGroups.collect { |group|
        var indexes, weights, weightSum;
        indexes = group.collect { |harmonic| harmonicNumbers.indexOf(harmonic) };
        weights = indexes.collect { |index| weightedShapes[index].abs };
        weightSum = weights.sum.max(1e-9);
        indexes.collect { |index, localIndex|
            preset[\panPositions][index] * weights[localIndex]
        }.sum / weightSum
    };

    SynthDef(defName, {
        |out = 0, gate = 1|
        var controlLag, energyLag, groupControls, stereoWidth;
        var wavetableBuffers, groupNorm, makeBank;
        var sourceA, sourceB, bankPosition;
        var source, delayed, delayMix;
        var energy, energyAmp, saturated, wet, signal, life, transportAlive;
        var saturationDrive, limiterDb;
        var voiceFrequenciesA, voiceFrequenciesB, voiceWeightsA, voiceWeightsB;
        var voiceFrequencyMinHz, voiceFrequencyMaxHz, polyphonySafetyTrim;

        controlLag = NamedControl.kr(
            \controlLag, preset[\controlLag]
        ).clip(0.02, 8);
        energyLag = NamedControl.kr(
            \energyLag, preset[\energyLag]
        ).clip(0.02, 8);
        groupControls = NamedControl.kr(
            \groupAmplitudes, preset[\baseGroups]
        ).collect { |value|
            VarLag.kr(value.clip(0, 1), controlLag, warp: -4)
        };
        stereoWidth = NamedControl.kr(
            \stereoWidth, preset[\stereoWidth]
        ).clip(0, 1);
        voiceFrequencyMinHz = NamedControl.kr(
            \voiceFrequencyMinHz, preset[\voiceFrequencyMinHz]
        ).clip(20, 200);
        voiceFrequencyMaxHz = NamedControl.kr(
            \voiceFrequencyMaxHz, preset[\voiceFrequencyMaxHz]
        ).clip(200, 2000);
        polyphonySafetyTrim = NamedControl.kr(
            \polyphonySafetyTrim, preset[\polyphonySafetyTrim]
        ).clip(0.5, 1.0);
        voiceFrequenciesA = NamedControl.kr(
            \voiceFrequenciesA, defaultVoiceFrequencies
        ).collect { |value| value.clip(voiceFrequencyMinHz, voiceFrequencyMaxHz) };
        voiceFrequenciesB = NamedControl.kr(
            \voiceFrequenciesB, defaultVoiceFrequencies
        ).collect { |value| value.clip(voiceFrequencyMinHz, voiceFrequencyMaxHz) };
        voiceWeightsA = NamedControl.kr(
            \voiceWeightsA, defaultVoiceWeights
        ).collect { |value| value.clip(0, 1) };
        voiceWeightsB = NamedControl.kr(
            \voiceWeightsB, defaultVoiceWeights
        ).collect { |value| value.clip(0, 1) };
        wavetableBuffers = groupWavetables.collect { |wavetable|
            LocalBuf.newFrom(wavetable)
        };
        groupNorm = (groupControls.collect { |value, index|
            (value * groupEnergyScales[index]).squared
        }.sum + 1e-9).sqrt;
        makeBank = { |frequencies, weights|
            var weightNorm, groups;
            // L2 normalization holds aggregate signal energy approximately
            // steady as weighted polyphony changes. The fixed safety trim and
            // final limiter cover correlated worst cases.
            weightNorm = (weights.collect(_.squared).sum + 1e-9).sqrt;
            groups = wavetableBuffers.collect { |buffer, index|
                var voiceMix;
                voiceMix = Mix(Osc.ar(
                    buffer,
                    frequencies,
                    0,
                    weights / weightNorm
                ));
                Pan2.ar(
                    voiceMix
                        * groupControls[index]
                        / groupNorm,
                    groupPanPositions[index].clip(-1, 1) * stereoWidth
                )
            };
            LeakDC.ar(Mix(groups)) * polyphonySafetyTrim;
        };
        sourceA = makeBank.value(voiceFrequenciesA, voiceWeightsA);
        sourceB = makeBank.value(voiceFrequenciesB, voiceWeightsB);
        bankPosition = VarLag.kr(
            NamedControl.kr(\voicingBank, 0).clip(0, 1),
            NamedControl.kr(
                \voicingCrossfade, preset[\voicingCrossfade]
            ).clip(0.1, 5),
            warp: \sin
        ) * 2 - 1;
        source = XFade2.ar(sourceA, sourceB, bankPosition);

        // Fixed, feedback-free and unmodulated cross-channel delay.
        delayed = [
            DelayC.ar(source[1], 0.08,
                NamedControl.kr(
                    \delayTimeLeft, preset[\delayTimeLeft]
                ).clip(0.001, 0.08)),
            DelayC.ar(source[0], 0.08,
                NamedControl.kr(
                    \delayTimeRight, preset[\delayTimeRight]
                ).clip(0.001, 0.08))
        ];
        delayMix = NamedControl.kr(
            \delayMix, preset[\delayMix]
        ).clip(0, 0.15);
        source = XFade2.ar(source, delayed, (delayMix * 2) - 1);

        // Energy remains strictly post-spectrum and pre-effect.
        energy = VarLag.kr(
            NamedControl.kr(
                \masterEnergy, preset[\masterEnergy]
            ).clip(0, 1),
            energyLag,
            warp: -4
        );
        energyAmp = energy.linlin(
            0, 1,
            NamedControl.kr(\energyMinDb, preset[\energyMinDb]),
            NamedControl.kr(\energyMaxDb, preset[\energyMaxDb])
        ).dbamp;
        source = source * energyAmp;

        saturationDrive = NamedControl.kr(
            \saturationDrive, preset[\saturationDrive]
        ).clip(1, 2);
        saturated = (source * saturationDrive).tanh / saturationDrive;
        wet = GVerb.ar(
            saturated.sum * 0.5,
            roomsize: NamedControl.kr(
                \reverbRoom, preset[\reverbRoom]
            ).clip(8, 80),
            revtime: NamedControl.kr(
                \reverbTime, preset[\reverbTime]
            ).clip(0.5, 12),
            damping: NamedControl.kr(
                \reverbDamping, preset[\reverbDamping]
            ).clip(0, 1),
            inputbw: NamedControl.kr(
                \reverbInputBw, preset[\reverbInputBw]
            ).clip(0.1, 1),
            spread: NamedControl.kr(
                \reverbSpread, preset[\reverbSpread]
            ).clip(0, 43),
            drylevel: 0,
            earlyreflevel: NamedControl.kr(
                \reverbEarly, preset[\reverbEarly]
            ).clip(0, 1),
            taillevel: NamedControl.kr(
                \reverbTail, preset[\reverbTail]
            ).clip(0, 1),
            maxroomsize: 80
        );
        signal = XFade2.ar(
            saturated,
            wet,
            (NamedControl.kr(
                \reverbMix, preset[\reverbMix]
            ).clip(0, 1) * 2) - 1
        );

        life = EnvGen.kr(
            Env.asr(
                NamedControl.kr(\attack, preset[\attack]).clip(0.05, 8),
                1,
                NamedControl.kr(\release, preset[\release]).clip(0.1, 15),
                curve: -4
            ),
            gate,
            doneAction: 2
        );
        transportAlive = LagUD.kr(
            NamedControl.kr(\transportAlive, 0).clip(0, 1),
            0.05,
            NamedControl.kr(
                \watchdogFade, preset[\watchdogFade]
            ).clip(0.05, 4)
        );
        limiterDb = NamedControl.kr(
            \limiterDb, preset[\limiterDb]
        ).clip(-12, -0.1);
        signal = Limiter.ar(
            signal.sanitize
                * NamedControl.kr(
                    \outputTrim, preset[\outputTrim]
                ).clip(0, 1)
                * transportAlive
                * life,
            limiterDb.dbamp,
            0.01
        );
        // A final bounded guard catches pathological startup samples from the
        // persistent local-wavetable/effect graph without changing normal audio.
        signal = Clip.ar(signal.sanitize, limiterDb.dbamp.neg, limiterDb.dbamp);
        Out.ar(out, signal);
    });
};

// DISCONNECTED MANUAL AUDITION: one persistent additive harmonic field.
//
// No /eeg/organism/frame OSCdef, LSL, Python, FieldTrip, Redis, clocked sound,
// random source, note trigger, or autonomous modulation is created here.
// This file never boots, reboots, or quits the existing server.

(
var here, library, presets, audition, defaultName, defaultPreset;
var def, state, oldState, setGroups, setEnergy, setPreset;
var auditionGroup, sweepMaster, sweepBrightness, sweepGroups, stop;

here = PathName(thisProcess.nowExecutingPath).pathOnly;
thisProcess.interpreter.executeFile(here +/+ "eeg_harmonic_field_core.scd");
thisProcess.interpreter.executeFile(here +/+ "eeg_harmonics_preset_support.scd");
library = thisProcess.interpreter.executeFile(here +/+ "eeg_harmonics_manual_config.scd");
presets = library[\presets];
audition = library[\audition];
defaultName = library[\defaultPreset];
defaultPreset = presets[defaultName];

oldState = ~eegHarmonicsManual;
if(oldState.notNil and: { oldState[\stop].notNil }) {
    oldState[\stop].value(true);
};

state = IdentityDictionary.new;
state[\library] = library;
state[\presets] = presets;
state[\audition] = audition;
state[\presetName] = defaultName;
state[\preset] = defaultPreset.copy;
state[\stopping] = false;
~eegHarmonicsManual = state;

setGroups = { |g1, g2, g3, g4|
    var values;
    values = if(g1.isNil) {
        state[\preset][\baseGroups].copy
    } {
        [g1, g2, g3, g4].collect { |value| value.asFloat.clip(0, 1) }
    };
    state[\synth].tryPerform(\setn, \groupAmplitudes, values);
    ("Harmonic groups: " ++ values).postln;
};
setEnergy = { |value|
    var target;
    target = value ? state[\preset][\masterEnergy];
    target = target.asFloat.clip(0, 1);
    state[\synth].tryPerform(\set, \masterEnergy, target);
    ("Harmonics master energy: " ++ target).postln;
};
setPreset = { |name = \warm_organic|
    var key, preset;
    key = name.asSymbol;
    preset = presets[key];
    if(preset.isNil) {
        ("Unknown harmonic preset: " ++ key
            ++ ". Available: " ++ presets.keys.asArray.sort).warn;
    } {
        state[\sweep].tryPerform(\stop);
        state[\presetName] = key;
        state[\preset] = preset.copy;
        ~applyEegHarmonicPreset.value(state[\synth], preset);
        ("Harmonic preset -> " ++ key ++ " (same persistent Synth)").postln;
    };
};
auditionGroup = { |oneBasedIndex = 1|
    var values, index;
    index = oneBasedIndex.asInteger.clip(1, 4) - 1;
    values = [0, 0, 0, 0];
    values[index] = 1;
    setGroups.value(*values);
    ("Harmonics isolated group " ++ (index + 1)).postln;
};

// Finite, manually invoked control demonstrations. No routine loops.
sweepMaster = {
    state[\sweep].tryPerform(\stop);
    state[\sweep] = Routine({
        setGroups.value(*state[\preset][\baseGroups]);
        setEnergy.value(audition[\masterLow]);
        audition[\masterStageSeconds].wait;
        setEnergy.value(audition[\masterHigh]);
        audition[\masterStageSeconds].wait;
        setEnergy.value(audition[\masterLow]);
    }).play(AppClock);
};
sweepBrightness = {
    state[\sweep].tryPerform(\stop);
    state[\sweep] = Routine({
        setEnergy.value(state[\preset][\masterEnergy]);
        setGroups.value(*audition[\warmGroups]);
        audition[\spectrumStageSeconds].wait;
        setGroups.value(*audition[\brightGroups]);
        audition[\spectrumStageSeconds].wait;
        setGroups.value(*audition[\warmGroups]);
    }).play(AppClock);
};
sweepGroups = {
    state[\sweep].tryPerform(\stop);
    state[\sweep] = Routine({
        4.do { |index|
            auditionGroup.value(index + 1);
            audition[\groupStageSeconds].wait;
        };
        setGroups.value(*state[\preset][\baseGroups]);
    }).play(AppClock);
};
stop = { |immediate = false|
    if(state[\stopping].not) {
        state[\stopping] = true;
        state[\sweep].tryPerform(\stop);
        if(immediate) {
            state[\group].tryPerform(\freeAll);
            state[\group].tryPerform(\free);
        } {
            state[\synth].tryPerform(\set, \gate, 0);
            Routine({
                (state[\preset][\release] + 0.25).wait;
                state[\group].tryPerform(\free);
            }).play(AppClock);
        };
        "Disconnected Harmonics manual field stopped.".postln;
    };
};

state[\setGroups] = setGroups;
state[\setEnergy] = setEnergy;
state[\setPreset] = setPreset;
state[\auditionGroup] = auditionGroup;
state[\sweepMaster] = sweepMaster;
state[\sweepBrightness] = sweepBrightness;
state[\sweepGroups] = sweepGroups;
state[\stop] = stop;

if(s.serverRunning) {
    Routine({
        var group, synth;
        def = ~makeEegHarmonicFieldSynthDef.value(
            \eegManualHarmonicField,
            defaultPreset
        );
        def.add;
        s.sync;
        if(state[\stopping].not) {
            group = Group.tail(s);
            synth = Synth.tail(group, \eegManualHarmonicField);
            state[\group] = group;
            state[\synth] = synth;
            "DISCONNECTED EEG HARMONICS PRESET PALETTE READY".postln;
            ("Preset: " ++ state[\presetName]).postln;
            "Stable tree: one Group + one continuous Synth.".postln;
            "No live EEG OSC endpoint was registered.".postln;
            "Switch: ~eegHarmonicsManual[\\setPreset].value(\\warm_organic);".postln;
            "        \\air_glass or \\dark_mineral".postln;
        };
    }).play(AppClock);
} {
    "Harmonics palette NOT started: start the existing scsynth/SuperDirt server, then evaluate again.".warn;
};
)

// Language-side preset helpers shared by the manual engine.
// This file creates no Synth, OSC endpoint, clock, or server connection.

~eegHarmonicScalarPresetKeys = [
    \fundamental, \harmonicCount, \harmonicRollOff,
    \masterEnergy, \energyMinDb, \energyMaxDb,
    \controlLag, \energyLag, \stereoWidth, \saturationDrive,
    \delayMix, \delayTimeLeft, \delayTimeRight,
    \reverbMix, \reverbRoom, \reverbTime, \reverbDamping,
    \reverbInputBw, \reverbSpread, \reverbEarly, \reverbTail,
    \outputTrim, \limiterDb, \attack, \release
];

~applyEegHarmonicPreset = { |synth, preset|
    var scalarArgs;
    scalarArgs = ~eegHarmonicScalarPresetKeys.collect { |key|
        [key, preset[key]]
    }.flat;
    synth.set(*scalarArgs);
    synth.setn(\groupAmplitudes, preset[\baseGroups]);
    synth.setn(\groupTrims, preset[\groupTrims]);
    synth.setn(\groupLoudnessComp, preset[\groupLoudnessComp]);
    synth.setn(\panPositions, preset[\panPositions]);
};

// PHASE 1B: one-debater sustained harmonic EEG organism.
//
// Evaluate this block only after an existing SuperDirt/scsynth server is running.
// This file never boots or reboots the server. Python's unchanged control frame is:
// F3 energy/centroid/mobility, F4 E/C/M, C3 E/C/M, C4 E/C/M,
// P3 E/C/M, P4 E/C/M (18 floats, nominally 0..1).

(
var oldState, state, configOrder, defaults, clampUnit, stopEngine, startEngine;

oldState = ~eegOrganism;
if(oldState.notNil and: { oldState[\stop].notNil }) {
    "EEG organism: releasing previously evaluated engine before replacement.".postln;
    oldState[\stop].value(true);
};

// Keep this order synchronized with CONFIG_PATHS in src/organism_osc.py.
configOrder = [
    \energyMinDb, \energyMaxDb, \energyLag,
    \tiltMin, \tiltMax, \centroidCompDb, \centroidLag,
    \motionRateMin, \motionRateMax, \motionDepthMin, \motionDepthMax, \mobilityLag,
    \varLagCurve, \fundamental,
    \pH1, \pH2, \pH3, \pH4,
    \cH1, \cH2, \cH3, \cH4,
    \fH1, \fH2, \fH3, \fH4,
    \cellLevel, \reverbMix, \reverbRoom, \reverbDamp,
    \masterLevel, \limiterLevel, \attack, \release, \watchdogFade,
    \panF3, \panF4, \panC3, \panC4, \panP3, \panP4
];

defaults = (
    energyMinDb: -36.0, energyMaxDb: -16.0, energyLag: 0.35,
    tiltMin: -0.85, tiltMax: 0.85, centroidCompDb: -1.0, centroidLag: 0.45,
    motionRateMin: 0.08, motionRateMax: 5.0,
    motionDepthMin: 0.05, motionDepthMax: 0.45, mobilityLag: 0.30,
    varLagCurve: -3.0, fundamental: 73.42,
    pH1: 1.0, pH2: 2.0, pH3: 3.0, pH4: 4.0,
    cH1: 3.0, cH2: 4.0, cH3: 5.0, cH4: 6.0,
    fH1: 6.0, fH2: 8.0, fH3: 10.0, fH4: 12.0,
    cellLevel: 0.28,
    reverbMix: 0.16, reverbRoom: 0.72, reverbDamp: 0.58,
    masterLevel: 0.42, limiterLevel: 0.82,
    attack: 0.35, release: 1.5, watchdogFade: 0.8,
    panF3: -0.38, panF4: 0.38,
    panC3: -0.28, panC4: 0.28,
    panP3: -0.20, panP4: 0.20
);

state = IdentityDictionary.new;
state[\config] = defaults.copy;
state[\configOrder] = configOrder;
state[\frameCount] = 0;
state[\timedOut] = true;
state[\stopping] = false;
~eegOrganism = state;

clampUnit = { |item|
    var value;
    value = try { item.asFloat } { 0.0 };
    if(value.isNaN) { value = 0.0 };
    value.clip(0.0, 1.0);
};

stopEngine = { |immediate = false|
    var group, bus, releaseTime;
    group = state[\group];
    bus = state[\bus];
    if(immediate and: { state[\stopping] }) {
        state[\releaseTask].tryPerform(\stop);
        group.tryPerform(\freeAll);
        group.tryPerform(\free);
        bus.tryPerform(\free);
        "EEG organism: in-progress old release freed for replacement.".postln;
    } {
        if(state[\stopping].not) {
            state[\stopping] = true;
            [\eegOrganismFrame, \eegOrganismConfig, \eegOrganismAudition,
                \eegOrganismStop].do { |key| OSCdef(key).tryPerform(\free) };
            state[\watchdog].tryPerform(\stop);
            releaseTime = state[\config][\release].asFloat.clip(0.05, 10.0);
            if(group.notNil) {
                if(immediate) {
                    group.freeAll;
                    group.free;
                    bus.tryPerform(\free);
                } {
                    state[\cells].do { |node| node.set(\gate, 0) };
                    state[\mixer].set(\gate, 0);
                    state[\releaseTask] = Routine({
                        (releaseTime + 0.25).wait;
                        group.freeAll;
                        group.free;
                        bus.tryPerform(\free);
                    }).play(AppClock);
                };
            };
            if(immediate) {
                "EEG organism: old engine freed (immediate replacement cleanup).".postln;
            } {
                "EEG organism: graceful release started.".postln;
            };
        };
    };
};
state[\stop] = stopEngine;

startEngine = {
    Routine({
        var group, bus, cells, mixer, commonArgs, applyConfig;

        // One deterministic sustained source design serves all six cells.
        // Family identity comes only from configurable harmonic assignments.
        SynthDef(\eegOrgHarmonicCell, {
            |outBus = 0, gate = 1, audition = 1,
            energy = 0.65, centroid = 0.5, mobility = 0.25,
            pan = 0, side = -1, motionPhase = 0,
            fundamental = 73.42, h1 = 1, h2 = 2, h3 = 3, h4 = 4,
            energyMinDb = -36, energyMaxDb = -16, energyLag = 0.35,
            tiltMin = -0.85, tiltMax = 0.85, centroidCompDb = -1,
            centroidLag = 0.45,
            motionRateMin = 0.08, motionRateMax = 5,
            motionDepthMin = 0.05, motionDepthMax = 0.45,
            mobilityLag = 0.30, varLagCurve = -3,
            cellLevel = 0.28, attack = 0.35, release = 1.5|
            var e, c, m, energyDb, amplitude, tilt, blend;
            var frequencies, phases, oscillators, darkWeights, brightWeights;
            var weights, weightNorm, harmonicBody, centroidGain;
            var motionRate, motionDepth, motionNorm, motion, life, signal;

            // ENERGY: only smoothed cell amplitude, on a perceptual dB scale.
            e = Lag.kr(energy.clip(0, 1), energyLag.clip(0.001, 10));
            energyDb = e.linlin(0, 1, energyMinDb.clip(-80, -3),
                energyMaxDb.clip(-80, -3).max(energyMinDb.clip(-80, -3)));
            amplitude = energyDb.dbamp;

            // CENTROID: normalized spectral tilt across the same four harmonics.
            // Normalizing the weight vector keeps oscillator RMS comparatively stable.
            c = VarLag.kr(centroid.clip(0, 1), centroidLag.clip(0.001, 10),
                varLagCurve.clip(-8, 8));
            tilt = c.linlin(0, 1, tiltMin.clip(-1, 1), tiltMax.clip(-1, 1));
            blend = (tilt + 1) * 0.5;
            darkWeights = [1.0, 0.72, 0.30, 0.10];
            brightWeights = [0.28, 0.58, 0.86, 1.0];
            weights = (darkWeights * (1 - blend)) + (brightWeights * blend);
            weightNorm = (weights.squared.sum + 0.0001).sqrt;

            frequencies = fundamental.clip(30, 220) * [h1, h2, h3, h4].collect(_.clip(1, 32));
            phases = [0.0, 0.41, 0.87, 1.31] + (side.clip(-1, 1) * 0.19);
            oscillators = SinOsc.ar(frequencies, phases);
            harmonicBody = Mix(oscillators * weights) / weightNorm;
            centroidGain = (c * centroidCompDb.clip(-12, 12)).dbamp;

            // MOBILITY: continuous deterministic AM only; no triggers or notes.
            // Division by sqrt(1 + depth^2/2) compensates sine-AM RMS.
            m = VarLag.kr(mobility.clip(0, 1), mobilityLag.clip(0.001, 10),
                varLagCurve.clip(-8, 8));
            motionRate = m.linexp(0, 1, motionRateMin.clip(0.01, 20),
                motionRateMax.clip(0.02, 20).max(motionRateMin.clip(0.01, 20)));
            motionDepth = m.linlin(0, 1, motionDepthMin.clip(0, 0.9),
                motionDepthMax.clip(0, 0.9).max(motionDepthMin.clip(0, 0.9)));
            motionNorm = (1 + (motionDepth.squared * 0.5)).sqrt;
            motion = (1 + (SinOsc.kr(motionRate, motionPhase) * motionDepth)) / motionNorm;

            life = EnvGen.kr(Env.asr(attack.clip(0.01, 5), 1,
                release.clip(0.05, 10)), gate, doneAction: 2);
            signal = harmonicBody * amplitude * centroidGain * motion;
            signal = signal * cellLevel.clip(0, 0.8) * Lag.kr(audition.clip(0, 1), 0.08) * life;
            Out.ar(outBus, Pan2.ar(LeakDC.ar(signal), pan.clip(-1, 1)));
        }).add;

        SynthDef(\eegOrgMixer, {
            |inBus = 0, out = 0, gate = 1, alive = 0,
            reverbMix = 0.16, reverbRoom = 0.72, reverbDamp = 0.58,
            masterLevel = 0.42, limiterLevel = 0.82,
            attack = 0.35, release = 1.5, watchdogFade = 0.8|
            var dry, wet, signal, watchdog, life;
            dry = LeakDC.ar(In.ar(inBus, 2));
            // Fixed global space: no EEG control reaches these parameters.
            wet = FreeVerb2.ar(dry[0], dry[1], 1,
                reverbRoom.clip(0, 1), reverbDamp.clip(0, 1));
            signal = XFade2.ar(dry, wet, (reverbMix.clip(0, 1) * 2) - 1);
            watchdog = LagUD.kr(alive.clip(0, 1), 0.04,
                watchdogFade.clip(0.05, 10));
            life = EnvGen.kr(Env.asr(attack.clip(0.01, 5), 1,
                release.clip(0.05, 10)), gate, doneAction: 2);
            signal = Limiter.ar(signal * masterLevel.clip(0, 0.8) * watchdog * life,
                limiterLevel.clip(0.1, 0.99), 0.01);
            // Sum this organism into stereo without replacing SuperDirt output.
            Out.ar(out, signal);
        }).add;

        s.sync;
        if(state[\stopping]) { nil } {
            bus = Bus.audio(s, 2);
            group = Group.tail(s);
            state[\bus] = bus;
            state[\group] = group;

            commonArgs = [
                \outBus, bus.index, \fundamental, defaults[\fundamental],
                \energyMinDb, defaults[\energyMinDb], \energyMaxDb, defaults[\energyMaxDb],
                \energyLag, defaults[\energyLag], \tiltMin, defaults[\tiltMin],
                \tiltMax, defaults[\tiltMax], \centroidCompDb, defaults[\centroidCompDb],
                \centroidLag, defaults[\centroidLag],
                \motionRateMin, defaults[\motionRateMin], \motionRateMax, defaults[\motionRateMax],
                \motionDepthMin, defaults[\motionDepthMin], \motionDepthMax, defaults[\motionDepthMax],
                \mobilityLag, defaults[\mobilityLag], \varLagCurve, defaults[\varLagCurve],
                \cellLevel, defaults[\cellLevel], \attack, defaults[\attack], \release, defaults[\release]
            ];
            cells = [
                Synth.tail(group, \eegOrgHarmonicCell, commonArgs ++ [
                    \h1, defaults[\fH1], \h2, defaults[\fH2], \h3, defaults[\fH3], \h4, defaults[\fH4],
                    \pan, defaults[\panF3], \side, -1, \motionPhase, 0.3]),
                Synth.tail(group, \eegOrgHarmonicCell, commonArgs ++ [
                    \h1, defaults[\fH1], \h2, defaults[\fH2], \h3, defaults[\fH3], \h4, defaults[\fH4],
                    \pan, defaults[\panF4], \side, 1, \motionPhase, 2.1]),
                Synth.tail(group, \eegOrgHarmonicCell, commonArgs ++ [
                    \h1, defaults[\cH1], \h2, defaults[\cH2], \h3, defaults[\cH3], \h4, defaults[\cH4],
                    \pan, defaults[\panC3], \side, -1, \motionPhase, 0.9]),
                Synth.tail(group, \eegOrgHarmonicCell, commonArgs ++ [
                    \h1, defaults[\cH1], \h2, defaults[\cH2], \h3, defaults[\cH3], \h4, defaults[\cH4],
                    \pan, defaults[\panC4], \side, 1, \motionPhase, 2.7]),
                Synth.tail(group, \eegOrgHarmonicCell, commonArgs ++ [
                    \h1, defaults[\pH1], \h2, defaults[\pH2], \h3, defaults[\pH3], \h4, defaults[\pH4],
                    \pan, defaults[\panP3], \side, -1, \motionPhase, 1.4]),
                Synth.tail(group, \eegOrgHarmonicCell, commonArgs ++ [
                    \h1, defaults[\pH1], \h2, defaults[\pH2], \h3, defaults[\pH3], \h4, defaults[\pH4],
                    \pan, defaults[\panP4], \side, 1, \motionPhase, 3.2])
            ];
            mixer = Synth.tail(group, \eegOrgMixer, [
                \inBus, bus.index,
                \reverbMix, defaults[\reverbMix], \reverbRoom, defaults[\reverbRoom],
                \reverbDamp, defaults[\reverbDamp],
                \masterLevel, defaults[\masterLevel], \limiterLevel, defaults[\limiterLevel],
                \attack, defaults[\attack], \release, defaults[\release],
                \watchdogFade, defaults[\watchdogFade]
            ]);
            state[\cells] = cells;
            state[\mixer] = mixer;
            state[\lastFrameAt] = Main.elapsedTime;

            applyConfig = {
                var cfg, shared;
                cfg = state[\config];
                shared = [
                    \fundamental, cfg[\fundamental],
                    \energyMinDb, cfg[\energyMinDb], \energyMaxDb, cfg[\energyMaxDb],
                    \energyLag, cfg[\energyLag], \tiltMin, cfg[\tiltMin],
                    \tiltMax, cfg[\tiltMax], \centroidCompDb, cfg[\centroidCompDb],
                    \centroidLag, cfg[\centroidLag],
                    \motionRateMin, cfg[\motionRateMin], \motionRateMax, cfg[\motionRateMax],
                    \motionDepthMin, cfg[\motionDepthMin], \motionDepthMax, cfg[\motionDepthMax],
                    \mobilityLag, cfg[\mobilityLag], \varLagCurve, cfg[\varLagCurve],
                    \cellLevel, cfg[\cellLevel], \attack, cfg[\attack], \release, cfg[\release]
                ];
                cells.do { |node| node.set(*shared) };
                cells[0].set(\h1, cfg[\fH1], \h2, cfg[\fH2], \h3, cfg[\fH3], \h4, cfg[\fH4], \pan, cfg[\panF3]);
                cells[1].set(\h1, cfg[\fH1], \h2, cfg[\fH2], \h3, cfg[\fH3], \h4, cfg[\fH4], \pan, cfg[\panF4]);
                cells[2].set(\h1, cfg[\cH1], \h2, cfg[\cH2], \h3, cfg[\cH3], \h4, cfg[\cH4], \pan, cfg[\panC3]);
                cells[3].set(\h1, cfg[\cH1], \h2, cfg[\cH2], \h3, cfg[\cH3], \h4, cfg[\cH4], \pan, cfg[\panC4]);
                cells[4].set(\h1, cfg[\pH1], \h2, cfg[\pH2], \h3, cfg[\pH3], \h4, cfg[\pH4], \pan, cfg[\panP3]);
                cells[5].set(\h1, cfg[\pH1], \h2, cfg[\pH2], \h3, cfg[\pH3], \h4, cfg[\pH4], \pan, cfg[\panP4]);
                mixer.set(
                    \reverbMix, cfg[\reverbMix], \reverbRoom, cfg[\reverbRoom],
                    \reverbDamp, cfg[\reverbDamp],
                    \masterLevel, cfg[\masterLevel], \limiterLevel, cfg[\limiterLevel],
                    \attack, cfg[\attack], \release, cfg[\release],
                    \watchdogFade, cfg[\watchdogFade]
                );
            };
            state[\applyConfig] = applyConfig;

            OSCdef(\eegOrganismFrame, { |message|
                var values;
                if(message.size == 19 and: { state[\stopping].not }) {
                    values = message.copyRange(1, 18).collect(clampUnit);
                    cells.do { |node, index|
                        node.set(
                            \energy, values[index * 3],
                            \centroid, values[(index * 3) + 1],
                            \mobility, values[(index * 3) + 2]
                        );
                    };
                    state[\lastFrameAt] = Main.elapsedTime;
                    state[\frameCount] = state[\frameCount] + 1;
                    if(state[\timedOut]) {
                        state[\timedOut] = false;
                        mixer.set(\alive, 1);
                        "EEG organism: input active.".postln;
                    };
                } {
                    "EEG organism: rejected frame (expected exactly 18 values).".warn;
                };
            }, '/eeg/organism/frame', recvPort: 57120);

            // Audition masks only multiply existing cells; they never create nodes.
            OSCdef(\eegOrganismAudition, { |message|
                var enabled;
                if(message.size == 7 and: { state[\stopping].not }) {
                    enabled = message.copyRange(1, 6).collect(clampUnit);
                    cells.do { |node, index| node.set(\audition, enabled[index]) };
                    ("EEG organism audition mask: " ++ enabled).postln;
                } {
                    "EEG organism: rejected audition mask (expected six values).".warn;
                };
            }, '/eeg/organism/audition', recvPort: 57120);

            OSCdef(\eegOrganismConfig, { |message|
                if(message.size == (configOrder.size + 1) and: { state[\stopping].not }) {
                    configOrder.do { |key, index|
                        var value;
                        value = try { message[index + 1].asFloat } { defaults[key] };
                        if(value.isNaN) { value = defaults[key] };
                        state[\config][key] = value;
                    };
                    state[\applyConfig].value;
                    "EEG organism: Phase 1B config values applied.".postln;
                } {
                    "EEG organism: rejected config packet (wrong value count).".warn;
                };
            }, '/eeg/organism/config', recvPort: 57120);

            OSCdef(\eegOrganismStop, {
                state[\stop].value(false);
            }, '/eeg/organism/stop', recvPort: 57120);

            state[\watchdog] = Routine({
                loop {
                    0.25.wait;
                    if(state[\stopping].not and: {
                        (Main.elapsedTime - state[\lastFrameAt]) > 2.0
                    } and: { state[\timedOut].not }) {
                        state[\timedOut] = true;
                        mixer.set(\alive, 0);
                        "EEG organism WATCHDOG: no frame for 2 seconds; fading to silence.".warn;
                    };
                };
            }).play(AppClock);

            "EEG ORGANISM PHASE 1B READY on UDP 57120".postln;
            "Stable tree: 1 dedicated group + 6 harmonic cells + 1 mixer (8 nodes total).".postln;
            ("Cell node IDs: " ++ cells.collect(_.nodeID) ++ "; mixer: " ++ mixer.nodeID).postln;
            "No noise beds, note triggers, grains, sequences, or autonomous pulses.".postln;
            "Waiting for /eeg/organism/frame; output remains silent until the first frame.".postln;
        };
    }).play(AppClock);
};
state[\start] = startEngine;

if(s.serverRunning) {
    state[\start].value;
} {
    "EEG organism NOT started: start SuperDirt/scsynth first, then evaluate this block again. No server was booted or rebooted.".warn;
};
)

// Graceful stop is in sound/stop_eeg_organism.scd or /eeg/organism/stop.

// ORGANISM V2 SYNTHETIC RECEIVER: one persistent additive harmonic field.
//
// Evaluate only after the existing SuperDirt/scsynth server is running.
// This file never boots, reboots, or quits the server. It reuses the tested
// harmonic-field SynthDef factory and creates one dedicated Group + one Synth.
// Both six-slot pitch banks live inside that one persistent Synth.
// Frame order: energy, centroid, mobility, spectralEntropy, novelty,
// delta, theta, alpha, beta.

(
var here, library, v2Config, preset, betaProfile, frameOrder, oldState, state;
var clampUnit, clampFrequency, stopReceiver, startReceiver;

here = PathName(thisProcess.nowExecutingPath).pathOnly;
thisProcess.interpreter.executeFile(here +/+ "eeg_harmonic_field_v2_core.scd");
thisProcess.interpreter.executeFile(here +/+ "eeg_harmonics_preset_support.scd");
library = thisProcess.interpreter.executeFile(here +/+ "eeg_harmonics_manual_config.scd");
v2Config = thisProcess.interpreter.executeFile(
    here +/+ "../config/eeg_organism_v2.scd"
);
preset = library[\presets][v2Config[\basePreset]].copy;
v2Config[\synthOverrides].keysValuesDo { |key, value| preset[key] = value };
preset[\harmonicGroups] = v2Config[\harmonicGroups];
preset[\voiceCapacity] = v2Config[\voiceCapacity];
betaProfile = v2Config[\betaProfiles][v2Config[\betaProfile]];
if(betaProfile.isNil) {
    Error("Unknown organism v2 beta profile: " ++ v2Config[\betaProfile]).throw
};
betaProfile.keysValuesDo { |key, value| preset[key] = value };
frameOrder = [
    \energy, \centroid, \mobility, \spectralEntropy, \novelty,
    \delta, \theta, \alpha, \beta
];

oldState = ~eegOrganismV2;
if(oldState.notNil and: { oldState[\stop].notNil }) {
    "Organism v2: freeing the previous receiver before replacement.".postln;
    oldState[\stop].value(true);
};

state = IdentityDictionary.new;
state[\frameOrder] = frameOrder;
state[\lastFrame] = IdentityDictionary.new;
state[\frameCount] = 0;
state[\lastFrameAt] = Main.elapsedTime;
state[\lastDisplayAt] = Main.elapsedTime - 1;
state[\timedOut] = true;
state[\stopping] = false;
state[\preset] = preset;
state[\config] = v2Config;
state[\previousFrameAt] = nil;
state[\receiveInterval] = 0.0;
state[\lastDisplayFrameCount] = 0;
state[\activeVoicingBank] = 0;
state[\voicingCount] = 0;
state[\lastVoicing] = IdentityDictionary.new;
state[\nextVoicingAt] = Main.elapsedTime;
~eegOrganismV2 = state;

clampUnit = { |item|
    var value;
    value = try { item.asFloat } { 0.0 };
    if(value.isNaN) { value = 0.0 };
    value.clip(0.0, 1.0);
};
clampFrequency = { |item|
    var value;
    value = try { item.asFloat } { preset[\fundamental].asFloat };
    if(value.isNaN) { value = preset[\fundamental].asFloat };
    value.clip(
        preset[\voiceFrequencyMinHz],
        preset[\voiceFrequencyMaxHz]
    );
};

stopReceiver = { |immediate = false|
    var group, synth, watchdogFade, release;
    group = state[\group];
    synth = state[\synth];
    watchdogFade = state[\preset][\watchdogFade].asFloat.clip(0.05, 4);
    release = state[\preset][\release].asFloat.clip(0.1, 15);

    if(immediate and: { state[\stopping] }) {
        state[\releaseTask].tryPerform(\stop);
        group.tryPerform(\freeAll);
        group.tryPerform(\free);
        "Organism v2: in-progress release freed for replacement.".postln;
    } {
        if(state[\stopping].not) {
            state[\stopping] = true;
            [\eegOrganismV2Frame, \eegOrganismV2Voicing,
                \eegOrganismV2Stop].do { |key|
                OSCdef(key).tryPerform(\free)
            };
            state[\watchdog].tryPerform(\stop);
            if(group.notNil) {
                if(immediate) {
                    group.freeAll;
                    group.free;
                } {
                    // Transport gain fades first, then the existing ASR releases.
                    synth.tryPerform(\set, \transportAlive, 0);
                    state[\releaseTask] = Routine({
                        (watchdogFade + 0.1).wait;
                        synth.tryPerform(\set, \gate, 0);
                        (release + 0.25).wait;
                        group.tryPerform(\free);
                    }).play(AppClock);
                };
            };
            if(immediate) {
                "Organism v2 receiver freed for replacement.".postln;
            } {
                "Organism v2 graceful release started; server remains running.".postln;
            };
        };
    };
};
state[\stop] = stopReceiver;

startReceiver = {
    Routine({
        var definition, group, synth;
        definition = ~makeEegOrganismV2HarmonicFieldSynthDef.value(
            \eegOrganismV2HarmonicField,
            preset
        );
        definition.add;
        s.sync;

        if(state[\stopping].not) {
            group = Group.tail(s);
            synth = Synth.tail(
                group, \eegOrganismV2HarmonicField,
                [\masterEnergy, 0, \transportAlive, 0]
            );
            state[\group] = group;
            state[\synth] = synth;
            state[\nodeIDs] = [group.nodeID, synth.nodeID];

            OSCdef(\eegOrganismV2Frame, { |message|
                var values, now, displayElapsed, effectiveHz, age;
                if(message.size == 10 and: { state[\stopping].not }) {
                    now = Main.elapsedTime;
                    values = message.copyRange(1, 9).collect(clampUnit);
                    frameOrder.do { |key, index|
                        state[\lastFrame][key] = values[index]
                    };

                    // The callback only updates the already-running Synth.
                    // No descriptor other than energy is a synthesis parameter yet.
                    synth.set(
                        \masterEnergy, values[0],
                        \transportAlive, 1
                    );
                    synth.setn(\groupAmplitudes, values.copyRange(5, 8));
                    if(state[\previousFrameAt].notNil) {
                        state[\receiveInterval] = now - state[\previousFrameAt]
                    };
                    state[\previousFrameAt] = now;
                    state[\lastFrameAt] = now;
                    state[\frameCount] = state[\frameCount] + 1;
                    if(state[\timedOut]) {
                        state[\timedOut] = false;
                        "Organism v2: synthetic input active.".postln;
                    };
                    displayElapsed = now - state[\lastDisplayAt];
                    if(displayElapsed >= v2Config[\diagnosticInterval]) {
                        effectiveHz = if(state[\frameCount] <= 1) {
                            0.0
                        } {
                            (
                                state[\frameCount] - state[\lastDisplayFrameCount]
                            ) / displayElapsed.max(0.001)
                        };
                        age = Main.elapsedTime - state[\lastFrameAt];
                        (
                            "Organism v2 rx count=" ++ state[\frameCount]
                            ++ " interval=" ++ state[\receiveInterval].round(0.001)
                            ++ "s effectiveHz=" ++ effectiveHz.round(0.01)
                            ++ " age=" ++ age.round(0.001)
                            ++ "s energy=" ++ values[0].round(0.001)
                            ++ " delta=" ++ values[5].round(0.001)
                            ++ " theta=" ++ values[6].round(0.001)
                            ++ " alpha=" ++ values[7].round(0.001)
                            ++ " beta=" ++ values[8].round(0.001)
                        ).postln;
                        state[\lastDisplayAt] = now;
                        state[\lastDisplayFrameCount] = state[\frameCount];
                    };
                } {
                    "Organism v2: rejected frame (expected exactly 9 values).".warn;
                };
            }, '/eeg/organism/v2/frame', recvPort: 57120);

            OSCdef(\eegOrganismV2Voicing, { |message|
                var frequencies, weights, nextBank, now;
                if(message.size == 13 and: { state[\stopping].not }) {
                    now = Main.elapsedTime;
                    frequencies = message.copyRange(1, 6).collect(clampFrequency);
                    weights = message.copyRange(7, 12).collect(clampUnit);
                    if(now < state[\nextVoicingAt]) {
                        "Organism v2: voicing ignored until current crossfade completes.".warn;
                    } {
                        if(weights.sum > 0.0001) {
                            // Populate only the inaudible bank, then crossfade the
                            // same persistent Synth. No server object is allocated.
                            nextBank = 1 - state[\activeVoicingBank];
                            if(nextBank == 0) {
                                synth.setn(\voiceFrequenciesA, frequencies);
                                synth.setn(\voiceWeightsA, weights);
                            } {
                                synth.setn(\voiceFrequenciesB, frequencies);
                                synth.setn(\voiceWeightsB, weights);
                            };
                            synth.set(\voicingBank, nextBank);
                            state[\activeVoicingBank] = nextBank;
                            state[\lastVoicing][\frequenciesHz] = frequencies;
                            state[\lastVoicing][\weights] = weights;
                            state[\voicingCount] = state[\voicingCount] + 1;
                            state[\nextVoicingAt] = now + preset[\voicingCrossfade];
                            ("Organism v2 voicing=" ++ state[\voicingCount]
                                ++ " bank=" ++ nextBank
                                ++ " frequenciesHz=" ++ frequencies
                                ++ " weights=" ++ weights).postln;
                        } {
                            "Organism v2: rejected silent voicing (all weights zero).".warn;
                        };
                    };
                } {
                    "Organism v2: rejected voicing (expected 6 frequencies + 6 weights).".warn;
                };
            }, '/eeg/organism/v2/voicing', recvPort: 57120);

            OSCdef(\eegOrganismV2Stop, {
                state[\stop].value(false);
            }, '/eeg/organism/v2/stop', recvPort: 57120);

            state[\watchdog] = Routine({
                loop {
                    0.25.wait;
                    if(state[\stopping].not and: {
                        (Main.elapsedTime - state[\lastFrameAt])
                            > v2Config[\watchdogTimeout]
                    } and: { state[\timedOut].not }) {
                        state[\timedOut] = true;
                        synth.set(\transportAlive, 0);
                        (
                            "Organism v2 WATCHDOG: no frame for "
                            ++ v2Config[\watchdogTimeout]
                            ++ " seconds; transport gain fading to silence."
                        ).warn;
                    };
                };
            }).play(AppClock);

            "ORGANISM V2 SYNTHETIC RECEIVER READY on UDP 57120".postln;
            "Stable tree: one dedicated Group + one persistent harmonic Synth.".postln;
            ("Node IDs: " ++ state[\nodeIDs]).postln;
            "Waiting for /eeg/organism/v2/frame; silent until the first frame.".postln;
            "Voicing endpoint: /eeg/organism/v2/voicing (6 frequencies + 6 weights).".postln;
            "Centroid, mobility, spectral entropy, and novelty are storage/display only.".postln;
            ("Exact harmonic groups: " ++ v2Config[\harmonicGroups]).postln;
            ("Beta profile: " ++ v2Config[\betaProfile]
                ++ " (ceiling=" ++ preset[\betaCeilingHz]
                ++ " Hz, upper tilt=" ++ preset[\betaUpperPartialTiltDb]
                ++ " dB, trim=" ++ preset[\betaTrim] ++ ")").postln;
        };
    }).play(AppClock);
};
state[\start] = startReceiver;

if(s.serverRunning) {
    state[\start].value;
} {
    "Organism v2 NOT started: start the existing SuperDirt/scsynth server, then evaluate again.".warn;
};
)

// Render one complete, identical-structure preset audition in scsynth NRT.

(
var here, library, presets, audition, presetName, preset, outputPath, def;
var score, options, time, gateTime, renderDuration, add, setGroups;

here = PathName(thisProcess.nowExecutingPath).pathOnly;
thisProcess.interpreter.executeFile(here +/+ "eeg_harmonic_field_core.scd");
library = thisProcess.interpreter.executeFile(here +/+ "eeg_harmonics_manual_config.scd");
presets = library[\presets];
audition = library[\audition];
presetName = ("EEG_HARMONIC_PRESET".getenv ? "warm_organic").asSymbol;
preset = presets[presetName];
outputPath = "EEG_HARMONIC_PRESET_OUTPUT".getenv;
if(preset.isNil) { ("Unknown preset: " ++ presetName).error; 1.exit };
if(outputPath.isNil) { "EEG_HARMONIC_PRESET_OUTPUT is required.".error; 1.exit };

def = ~makeEegHarmonicFieldSynthDef.value(\eegHarmonicPresetRender, preset);
score = List.new;
add = { |at, message| score.add([at, message]) };
setGroups = { |at, values|
    add.value(at, [\n_setn, 1000, \groupAmplitudes, 4] ++ values);
};

// Identical structure and timestamps for all three presets.
time = 0.0;
add.value(time, [\d_recv, def.asBytes,
    [\s_new, \eegHarmonicPresetRender, 1000, 0, 0]]);

// Base full mix.
time = time + audition[\baseSeconds];

// Master low / high / low with a fixed spectrum.
add.value(time, [\n_set, 1000, \masterEnergy, audition[\masterLow]]);
time = time + audition[\masterStageSeconds];
add.value(time, [\n_set, 1000, \masterEnergy, audition[\masterHigh]]);
time = time + audition[\masterStageSeconds];
add.value(time, [\n_set, 1000, \masterEnergy, audition[\masterLow]]);
time = time + audition[\masterReturnSeconds];

// Warm / bright / warm redistribution at preset baseline energy.
add.value(time, [\n_set, 1000, \masterEnergy, preset[\masterEnergy]]);
setGroups.value(time, audition[\warmGroups]);
time = time + audition[\spectrumStageSeconds];
setGroups.value(time, audition[\brightGroups]);
time = time + audition[\spectrumStageSeconds];
setGroups.value(time, audition[\warmGroups]);
time = time + audition[\spectrumStageSeconds];

// Groups 1 / 2 / 3 / 4 in isolation.
4.do { |index|
    var values;
    values = [0, 0, 0, 0];
    values[index] = 1;
    setGroups.value(time, values);
    time = time + audition[\groupStageSeconds];
};

// Return to preset base full mix.
setGroups.value(time, preset[\baseGroups]);
time = time + audition[\finalBaseSeconds];
gateTime = time;
add.value(gateTime, [\n_set, 1000, \gate, 0]);
renderDuration = gateTime + audition[\renderTailSeconds];
add.value(renderDuration, [\c_set, 0, 0]);

options = ServerOptions.new;
options.protocol = \tcp;
options.numOutputBusChannels = 2;
options.numInputBusChannels = 0;
options.sampleRate = 48000;
options.blockSize = 64;
options.memSize = 65536;

Score(score).recordNRT(
    outputFilePath: outputPath,
    sampleRate: 48000,
    headerFormat: "WAV",
    sampleFormat: "int24",
    options: options,
    duration: renderDuration,
    action: {
        ("RENDERED PRESET " ++ presetName ++ " -> " ++ outputPath).postln;
        0.exit;
    }
);
)

// Legacy six-file isolated renderer, retained for reproducibility.
// New preset comparison renders use render_eeg_harmonic_presets.scd.

(
var here, library, preset, audition, initialPreset, def;
var testName, outputPath, duration, renderDuration;
var changes, scoreMessages, options, groupMessage;

here = PathName(thisProcess.nowExecutingPath).pathOnly;
thisProcess.interpreter.executeFile(here +/+ "eeg_harmonic_field_core.scd");
library = thisProcess.interpreter.executeFile(here +/+ "eeg_harmonics_manual_config.scd");
preset = library[\presets][library[\defaultPreset]];
audition = library[\audition];
testName = "EEG_HARMONICS_TEST".getenv ? "master_energy";
outputPath = "EEG_HARMONICS_OUTPUT".getenv;
if(outputPath.isNil) { "EEG_HARMONICS_OUTPUT is required.".error; 1.exit };

initialPreset = preset.copy;
changes = List.new;
groupMessage = { |time, values|
    changes.add([time, [\n_setn, 1000, \groupAmplitudes, 4] ++ values]);
};

switch(testName,
    "master_energy", {
        duration = 12.0;
        initialPreset[\masterEnergy] = audition[\masterLow];
        changes.add([3.0, [\n_set, 1000, \masterEnergy, 1.00]]);
        changes.add([6.2, [\n_set, 1000, \masterEnergy, audition[\masterLow]]]);
    },
    "redistribution", {
        duration = 9.0;
        initialPreset[\baseGroups] = audition[\warmGroups];
        groupMessage.value(3.0, audition[\brightGroups]);
        groupMessage.value(6.2, audition[\warmGroups]);
    },
    "group1", { duration = 5.5; initialPreset[\baseGroups] = [1, 0, 0, 0] },
    "group2", { duration = 5.5; initialPreset[\baseGroups] = [0, 1, 0, 0] },
    "group3", { duration = 5.5; initialPreset[\baseGroups] = [0, 0, 1, 0] },
    "group4", { duration = 5.5; initialPreset[\baseGroups] = [0, 0, 0, 1] },
    { ("Unknown EEG_HARMONICS_TEST: " ++ testName).error; 1.exit }
);

def = ~makeEegHarmonicFieldSynthDef.value(
    \eegManualHarmonicFieldRender,
    initialPreset
);
renderDuration = duration + 4.7;
scoreMessages = List.new;
scoreMessages.add([0.0, [\d_recv, def.asBytes,
    [\s_new, \eegManualHarmonicFieldRender, 1000, 0, 0]]]);
changes.do { |item| scoreMessages.add(item) };
scoreMessages.add([duration, [\n_set, 1000, \gate, 0]]);
scoreMessages.add([renderDuration, [\c_set, 0, 0]]);

options = ServerOptions.new;
options.protocol = \tcp;
options.numOutputBusChannels = 2;
options.numInputBusChannels = 0;
options.sampleRate = 48000;
options.blockSize = 64;
options.memSize = 65536;

Score(scoreMessages).recordNRT(
    outputFilePath: outputPath,
    sampleRate: 48000,
    headerFormat: "WAV",
    sampleFormat: "int24",
    options: options,
    duration: renderDuration,
    action: {
        ("RENDERED " ++ testName ++ " -> " ++ outputPath).postln;
        0.exit;
    }
);
)

// Render one steady-state organism v2 LOW or HIGH condition in NRT.
(
var here, library, v2Config, preset, betaProfileName, betaProfile;
var field, level, outputPath, oscScorePath, archiveDirectory;
var groups, bandNames, bandIndex, definition, score, options;
var gateTime, renderDuration;

here = PathName(thisProcess.nowExecutingPath).pathOnly;
thisProcess.interpreter.executeFile(here +/+ "eeg_harmonic_field_v2_core.scd");
library = thisProcess.interpreter.executeFile(here +/+ "eeg_harmonics_manual_config.scd");
v2Config = thisProcess.interpreter.executeFile(
    here +/+ "../config/eeg_organism_v2.scd"
);
preset = library[\presets][v2Config[\basePreset]].copy;
v2Config[\synthOverrides].keysValuesDo { |key, value| preset[key] = value };
preset[\harmonicGroups] = v2Config[\harmonicGroups];
betaProfileName = ("EEG_ORGANISM_V2_BETA_PROFILE".getenv
    ? v2Config[\betaProfile].asString).asSymbol;
betaProfile = v2Config[\betaProfiles][betaProfileName];
if(betaProfile.isNil) {
    ("Unknown organism v2 beta profile: " ++ betaProfileName).error;
    1.exit
};
betaProfile.keysValuesDo { |key, value| preset[key] = value };

field = ("EEG_ORGANISM_V2_FIELD".getenv ? "energy").asSymbol;
level = ("EEG_ORGANISM_V2_LEVEL".getenv ? "low").asSymbol;
outputPath = "EEG_ORGANISM_V2_OUTPUT".getenv;
if(outputPath.isNil) { "EEG_ORGANISM_V2_OUTPUT is required.".error; 1.exit };
// Keep the temporary NRT score beside the requested workspace output instead
// of relying on a user-profile temp directory that may not be writable.
oscScorePath = outputPath ++ ".osc";
archiveDirectory = "EEG_ORGANISM_V2_ARCHIVE_DIR".getenv;
if(archiveDirectory.notNil) { Archive.archiveDir = archiveDirectory };

groups = preset[\baseGroups].copy;
if(field == \energy) {
    preset[\masterEnergy] = if(level == \high) { 1.0 } { 0.0 };
} {
    bandNames = [\delta, \theta, \alpha, \beta];
    bandIndex = bandNames.indexOf(field);
    if(bandIndex.isNil) { ("Unknown v2 field: " ++ field).error; 1.exit };
    preset[\masterEnergy] = 0.68;
    groups = [0.01, 0.01, 0.01, 0.01];
    groups[bandIndex] = if(level == \high) { 1.0 } { 0.0 };
};
preset[\baseGroups] = groups;

definition = ~makeEegOrganismV2HarmonicFieldSynthDef.value(
    \eegOrganismV2IsolatedRender,
    preset
);
gateTime = 6.0;
renderDuration = gateTime + preset[\release] + 0.5;
score = [
    [0.0, [\d_recv, definition.asBytes,
        [\s_new, \eegOrganismV2IsolatedRender, 1000, 0, 0,
            \transportAlive, 1]]],
    [gateTime, [\n_set, 1000, \gate, 0]],
    [renderDuration, [\c_set, 0, 0]]
];

options = ServerOptions.new;
options.protocol = \tcp;
options.numOutputBusChannels = 2;
options.numInputBusChannels = 0;
options.sampleRate = 48000;
options.blockSize = 64;
options.memSize = 65536;

Score(score).recordNRT(
    oscFilePath: oscScorePath,
    outputFilePath: outputPath,
    sampleRate: 48000,
    headerFormat: "WAV",
    sampleFormat: "int24",
    options: options,
    duration: renderDuration,
    action: {
        File.delete(oscScorePath);
        ("RENDERED V2 " ++ field ++ " " ++ level ++ " -> " ++ outputPath).postln;
        0.exit;
    }
);
)

